type ErrorCode int32

const (
	ErrorCode_ERROR_CODE_UNSPECIFIED ErrorCode = 0
	ErrorCode_ERROR_CODE_INVALID     ErrorCode = 1
	ErrorCode_ERROR_CODE_NOT_FOUND   ErrorCode = 2
	// ThreadCreate on a sensitive directory without Consent.sensitive.
	ErrorCode_ERROR_CODE_NEEDS_CONSENT ErrorCode = 3
	// ThreadRespond with a revision that is no longer current.
	ErrorCode_ERROR_CODE_STALE ErrorCode = 4
	// All session slots are busy; the thread is queued.
	ErrorCode_ERROR_CODE_QUEUED               ErrorCode = 5
	ErrorCode_ERROR_CODE_PROVIDER_UNAVAILABLE ErrorCode = 6
	ErrorCode_ERROR_CODE_NEEDS_LOGIN          ErrorCode = 7
	ErrorCode_ERROR_CODE_INTERNAL             ErrorCode = 8
)

